public double trimMean(int[] arr) {
  	// Find the smallest 5% of elements
	int smallest = (int)(arr.length * 0.05);
	quicksort(arr, 0, arr.length - 1, smallest);

	// Find the largest 5% of elements
	int largest = (int)(arr.length * 0.05);
	quicksort(arr, 0, arr.length - 1, arr.length - largest);

	// Calculate the mean of the remaining elements
	int sum = 0;
	for (int i = smallest; i < arr.length - largest; i++) {
		sum += arr[i];
	}
	return (double)sum / (arr.length - 2 * smallest);
}

private void quicksort(int[] arr, int left, int right, int index) {
	if (left >= right)
		return;
	int pivot = arr[index];
	int i = left;
	int j = right;
	while (i <= j) {
		while (arr[i] < pivot)
			i++;
		while (arr[j] > pivot)
			j--;
		if (i <= j) {
			swap(arr, i, j);
			i++;
			j--;
		}
	}
	quicksort(arr, left, j, index);
	quicksort(arr, i, right, index);
}

private void swap(int[] arr, int i, int j) {
	int temp = arr[i];
	arr[i] = arr[j];
	arr[j] = temp;
}

