package squarePermutations;

import java.util.Arrays;

public class SquarePermutations {

    public static int squarePermutations(int[] A) {
        if (A == null || A.length == 0) {
            return 0;
        }

        // Initialize a set to keep track of the elements in A
        Set<Integer> set = new HashSet<>();
        for (int i = 0; i < A.length; i++) {
            set.add(A[i]);
        }

        // Initialize a count to keep track of the number of permutations
        int count = 0;

        // Loop through each possible permutation of A
        for (int i = 0; i < A.length; i++) {
            // If the current permutation is a square, increment the count
            if (isSquarePermutation(A, set)) {
                count++;
            }

            // Swap the first and last elements of the permutation
            swap(A, i, A.length - 1 - i);
        }

        return count;
    }

    private static boolean isSquarePermutation(int[] A, Set<Integer> set) {
        // Check if the sum of each pair of adjacent elements is a perfect square
        for (int i = 0; i < A.length - 1; i++) {
            if (!isSquare(A[i] + A[i + 1])) {
                return false;
            }
        }

        // Check if all elements in the set have been used
        for (int element : set) {
            if (!A.contains(element)) {
                return false;
            }
        }

        return true;
    }

    private static boolean isSquare(int number) {
        // Check if the number is a perfect square
        int root = (int) Math.sqrt(number);
        return root * root == number;
    }

    private static void swap(int[] A, int i, int j) {
        int temp = A[i];
        A[i] = A[j];
        A[j] = temp;
    }
}
